"""docs/bench.md: the CratonBench card, generated from the code and the frozen record.

Like the data cards, it is written by ``craton bench cards`` and ``craton check`` fails if the
file drifts from what the code and ``craton/bench/frozen/`` say.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

