from craton.bench.tasks import CB01_BINS, TASKS, load_frozen

HEADER = (
    "<!-- Generated by `craton bench cards` from craton/bench/. Do not edit by hand:\n"
    "     `craton check` fails if this file drifts from the code. -->\n"
)

