def _velocity(summary: dict[str, Any]) -> list[str]:
    """CB-28's regions: pairs, the stations hidden in turn, the values graded."""
    out = ["| Region | Snapshot | Pairs | Stations hidden | Test values |", "|---|---|---|---|---|"]
    for region, snap in summary.get("snapshots", {}).items():
        r = summary[region]
        out.append(
            f"| `{region}` | `{snap}` | {r['pairs']} | {len(r['folds'])} of {r['stations']} "
            f"| {r['test_values']:,} |"
        )
    return out


def _sequences(summary: dict[str, Any]) -> list[str]:
    """CB-22's frozen sequences: where, when, how many quakes to score, how many to fit on."""
    from craton.bench.world import SEQUENCES

    out = [
        "| Sequence | Region | Half | mc | Scored quakes | Largest in window | ETAS fits on |",
        "|---|---|---|---|---|---|---|",
    ]
    for seq in SEQUENCES:
        v = summary[seq.key]
        scored = v.get(f"M>={v['mc'] + 1:g}", "·")
        out.append(
            f"| {seq.name} | {seq.region} | {seq.half.replace('_', '-')} | {v['mc']:g} | "
            f"{scored} | {v['largest']} | {v['fit_quakes']:,} |"
        )
    snaps = ", ".join(f"{r} `{i}`" for r, i in summary["snapshots"].items())
    return [*out, "", f"Snapshots: {snaps}."]


def _lons(lo: float, hi: float) -> str:
    return f"{-lo:g}-{-hi:g}° W" if hi <= 0 else f"{lo:g}-{hi:g}° E"


def _cases(summary: dict[str, Any]) -> list[str]:
    """CB-30's frozen cases: the box, the magnitudes, what is scored and what ETAS fits on."""
    from craton.bench.induced import CASES

    out = [
        "| Case | Forcing | Box | Cells | mc | Scored from | Scored quakes | Largest "
        "| ETAS fits on |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for c in CASES:
        v = summary[c.key]
        lat0, lat1, lon0, lon1 = v["box"]
        out.append(
            f"| {c.name} | {c.about} | {lat0:g}-{lat1:g}° N, {_lons(lon0, lon1)} | "
            f"{c.cell_deg:g}° | {c.mc:g} | {c.scored:g} | {v.get(f'M>={c.scored:g}', '·')} | "
            f"{v['largest']:.2f} | {v['fit_quakes']:,} |"
        )
    snaps = ", ".join(f"{r} `{i}`" for r, i in summary["snapshots"].items())
    return [*out, "", f"Snapshots: {snaps}."]


def _stress(summary: dict[str, Any]) -> list[str]:
    """CB-23's frozen regions: cells, records, how much a cell's own readings disagree."""
    from craton.bench.stress import CASES

    out = [
        "| Region | Half | Quakes read (before) | Cells | WSM records | Median spread in a cell |",
        "|---|---|---|---|---|---|",
    ]
    for c in CASES:
        v = summary[c.region]
        out.append(
            f"| {c.region.replace('_', ' ')} | {c.half.replace('_', '-')} | "
            f"{v['history_quakes']:,} M{c.mc:g}+ ({c.cut[:10]}) | {v['cells']} | "
            f"{v['records']:,} | {v['median_spread_deg']:g}° |"
        )
    snaps = ", ".join(f"{r} `{i}`" for r, i in summary["snapshots"].items())
    return [*out, "", f"Snapshots: {snaps}."]


def _mechanisms(summary: dict[str, Any]) -> list[str]:
    """CB-34's frozen regions: cells, non-quake records, mechanisms a method may read."""
    from craton.bench.stress import CASES

    out = [
        "| Region | Half | Mechanisms read (crust, before) | Cells | Non-quake records |",
        "|---|---|---|---|---|",
    ]
    for c in CASES:
        v = summary[c.region]
        out.append(
            f"| {c.region.replace('_', ' ')} | {c.half.replace('_', '-')} | "
            f"{v['mechanisms']:,} ({v['crustal_mechanisms']:,}, {c.cut[:10]}) | {v['cells']} | "
            f"{v['records']:,} |"
        )
    return [
        *out,
        "",
        f"Mechanisms: gcmt_world snapshot `{summary['mechanism_snapshot']}`; "
        f"{summary['non_quake_records']:,} non-quake WSM records worldwide.",
    ]


def _migration(summary: dict[str, Any]) -> list[str]:
    """CB-24's frozen sequences: how many cells lit, how many are scored, over how long."""
    out = [
        "| Sequence | Lights at | Cells lit in a year | Scored | Days to the last scored |",
        "|---|---|---|---|---|",
    ]
    for key, v in summary.items():
        if key == "snapshots":
            continue
        days = "·" if v["days_to_last_scored"] is None else f"{v['days_to_last_scored']:g}"
        out.append(f"| {key} | M{v['threshold']:g}+ | {v['lit']} | {v['scored']} | {days} |")
    snaps = ", ".join(f"{r} `{i}`" for r, i in summary["snapshots"].items())
    return [*out, "", f"Snapshots: {snaps}."]


def _bins() -> list[str]:
    out = ["| Instrument | Channel | Bin width | Edges |", "|---|---|---|---|"]
    for inst, bins in CB01_BINS.items():
        for b in bins:
            edges = "k·w" if not b.offset else f"k·w − {b.offset:g}"
            out.append(f"| `{inst}` | {b.channel} | {b.width:g} | {edges} |")
    return out


def _planets(summary: dict[str, Any]) -> list[str]:
    """CB-09's frozen planets against the real Apennines, statistic by statistic."""
    real = summary["real"]
    cols = [k for k in real if k != "largest"]
    out = [
        "| Catalogue | Seed | "
        + " | ".join(c.replace("_", " ") for c in cols)
        + " | gap | test M3+ |",
        "|---|---|" + "---|" * (len(cols) + 2),
        "| Real Apennines | · | " + " | ".join(f"{real[c]:.3g}" for c in cols) + " | 0 | · |",
    ]
    for kind, v in summary.items():
        if kind == "real":
            continue
        for seed, p in zip(v["seeds"], v["planets"], strict=True):
            stats = " | ".join(f"{p[c]:.3g}" for c in cols)
            name = kind.replace("_", " ")
            out.append(f"| {name} | {seed} | {stats} | {p['gap']:.2f} | {p['test_m3']} |")
    return out


def render() -> str:
    frozen: dict[str, Any] = load_frozen() or {}
    lines = [HEADER, "# CratonBench v1", ""]
    lines += [
        "Four tests, frozen before any model exists. A test's data and metric never change; "
        "a better test gets a new ID. Each is fingerprinted: the hash of its definition, its "
        "metric and every test file, and the ratchet refuses a run whose fingerprint differs.",
        "",
        f"Region `{frozen.get('region', '?')}`, data snapshot `{frozen.get('snapshot', '?')}`.",
        "",
        "## What is held out",
        "",
        "| Held out | From | To |",
        "|---|---|---|",
    ]
    for w in ERAS:
        lines.append(f"| {w.name.replace('_', ' ').title()} | {w.start[:10]} | {w.end[:10]} |")
    stations = frozen.get("heldout_stations", [])
    lines += [
        "",
        f"And {len(stations)} GNSS stations, one in ten, chosen by a salted hash among "
        "stations with at least two years of data, three visible neighbours within 50 km, and "
        "no day-to-day jump over "
        f"{definition()['heldout']['max_jump_m']:g} m: "
        + ", ".join(f"`{s}`" for s in stations)
        + ".",
        "",
        "## Training splits",
        "",
        "Cut from the snapshot and written to disk, every file named by its hash. "
        "`craton bench leaks` reads every shard back and fails on a single held-out token.",
        "",
        "| Split | For | Tokens | Left out | Manifest |",
        "|---|---|---|---|---|",
    ]
    for name, spec in SPLITS.items():
        s = frozen.get("splits", {}).get(name, {})
        lines.append(
            f"| `{name}` | {spec.purpose} | {s.get('tokens', 0):,} | {s.get('left_out', 0):,} "
            f"| `{s.get('id', '?')}` |"
        )
    for task_id, task in TASKS.items():
        f = frozen.get("tasks", {}).get(task_id, {})
        better = "lower is better" if task.direction == "lower" else "higher is better"
        lines += [
            "",
            f"## {task_id} · {task.name}",
            "",
            ABOUT.get(task_id, ""),
            "",
            f"- **Metric:** {task.metric} ({better})",
            f"- **Fingerprint:** `{f.get('fingerprint', '?')[:16]}`",
        ]
        summary = f.get("summary", {})
        if summary and task_id not in (
            "CB-09",
            "CB-22",
            "CB-23",
            "CB-24",
            "CB-28",
            "CB-30",
            "CB-32",
            "CB-34",
        ):
            parts = []
            for k, v in summary.items():
                if isinstance(v, dict):
                    v = ", ".join(
                        f"{a} {'/'.join(f'{x:g}' for x in b) if isinstance(b, list) else f'{b:,}'}"
                        for a, b in v.items()
                    )
                elif isinstance(v, int | float):
                    v = f"{v:,}"
                parts.append(f"{k.replace('_', ' ')} {v}")
            lines.append("- **Test data:** " + " · ".join(parts))
        if task_id == "CB-01":
            lines += ["", *_bins()]
        if task_id == "CB-09" and summary:
            lines += ["", *_planets(summary)]
        if task_id == "CB-22" and summary:
            lines += ["", *_sequences(summary)]
        if task_id == "CB-28" and summary:
            lines += ["", *_velocity(summary)]
        if task_id == "CB-30" and summary:
            lines += ["", *_cases(summary)]
        if task_id == "CB-23" and summary:
            lines += ["", *_stress(summary)]
        if task_id == "CB-24" and summary:
            lines += ["", *_migration(summary)]
        if task_id == "CB-34" and summary:
            lines += ["", *_mechanisms(summary)]
    lines += [
        "",
        "## Add a method",
        "",
        "Implement the task's protocol (`MaskedPredictor`, `Forecaster`, `GapFiller` or "
        "`EfficiencyReport` in `craton/bench/tasks.py`), register it with `register_method`, "
        "and run `craton bench run NAME`. The run lands in `results/pending/`; `craton ratchet "
        "--accept` puts it on the scoreboard if nothing got worse.",
        "",
    ]
    return "\n".join(lines)


def path(root: Path) -> Path:
    return root / "docs" / "bench.md"


def write(root: Path) -> Path:
    out = path(root)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render(), encoding="utf-8", newline="\n")
    return out


def drift_problem(root: Path) -> str | None:
    out = path(root)
    if not out.is_file():
        return "docs/bench.md is missing; run `craton bench cards`"
    if out.read_text(encoding="utf-8").replace("\r\n", "\n") != render():
        return "docs/bench.md is out of date; run `craton bench cards`"
    return None
